# Expected values are SymPy's outputs for the same calls (Laplace transforms).

skip_unless_full_tests()

skip_on_cran()

a <- Symbol("a", positive = TRUE); b <- Symbol("b", positive = TRUE); c <- Symbol("c", positive = TRUE); np <- Symbol("np", integer = TRUE, positive = TRUE)
t <- Symbol("t"); w <- Symbol("w"); x <- Symbol("x"); s <- Symbol("s")
f <- Function("f"); F <- Function("F"); g <- Function("g"); y <- Function("y"); Y <- Function("Y")
mi_fmt <- function(v) if (is.null(v)) "None" else if (is_sym(v)) gsub("\n", " ", sstr(v)) else paste0("(", paste(vapply(v, function(z) gsub("\n", " ", sstr(z)), ""), collapse = ", "), ")")

test_that("Laplace transforms match SymPy", {
  expect_equal(mi_fmt(laplace_transform(diff(y(t), t, 3), t, s, noconds = TRUE)), "s^3*LaplaceTransform(y(t), t, s) - s^2*y(0) - s*Subs(Derivative(y(t), t), t, 0) - Subs(Derivative(y(t), (t, 2)), t, 0)")
  expect_equal(mi_fmt(laplace_transform(42 * sin(w * t + x) ^ 2, t, s)), "(42*(-s*cos(2*x)/2 + w*sin(2*x))/(s^2 + 4*w^2) + 21/s, 2*Abs(im(w)), True)")
  expect_equal(mi_fmt(laplace_transform(cos(x + 3), x, s, simplify = TRUE)), "((s*cos(3) - sin(3))/(s^2 + 1), 0, True)")
  expect_equal(mi_fmt(laplace_transform(sin(a * t + b) ^ 2 * f(t), t, s)), "(LaplaceTransform(f(t), t, s)/2 - LaplaceTransform(f(t), t, -2*I*a + s)*exp(2*I*b)/4 - LaplaceTransform(f(t), t, 2*I*a + s)*exp(-2*I*b)/4, -oo, True)")
  expect_equal(mi_fmt(laplace_transform(sin(a * t + b) ^ 2 * f(t), t, s, noconds = TRUE)), "LaplaceTransform(f(t), t, s)/2 - LaplaceTransform(f(t), t, -2*I*a + s)*exp(2*I*b)/4 - LaplaceTransform(f(t), t, 2*I*a + s)*exp(-2*I*b)/4")
  expect_equal(mi_fmt(laplace_transform(sin(a * t) ^ 3 * cosh(b * t), t, s)), "((-27*a^3/2 - 3*a*s^2/4 - 3*a*(-9*a^2 + b^2)/4)/(81*a^4 + 18*a^2*b^2 + b^4 + s^4 + s^2*(18*a^2 - 2*b^2)) + (3*a^3/2 + 3*a*s^2/4 + 3*a*(-a^2 + b^2)/4)/(a^4 + 2*a^2*b^2 + b^4 + s^4 + s^2*(2*a^2 - 2*b^2)), b, True)")
  expect_equal(mi_fmt(laplace_transform(a * t + t ^ 2 + t ^ (as_sym(5) / 2), t, s)), "(a/s^2 + 2/s^3 + 15*sqrt(pi)/(8*s^(7/2)), 0, True)")
  expect_equal(mi_fmt(laplace_transform(b / (t + a), t, s)), "(-b*exp(-a*s)*Ei(-a*s), 0, True)")
  expect_equal(mi_fmt(laplace_transform(1 / sqrt(t + a), t, s)), "(sqrt(pi)*sqrt(1/s)*exp(a*s)*erfc(sqrt(a)*sqrt(s)), 0, True)")
  expect_equal(mi_fmt(laplace_transform(sqrt(t) / (t + a), t, s)), "(-pi*sqrt(a)*exp(a*s)*erfc(sqrt(a)*sqrt(s)) + sqrt(pi)*sqrt(1/s), 0, True)")
  expect_equal(mi_fmt(laplace_transform((t + a) ^ (-as_sym(3) / 2), t, s)), "(-2*sqrt(pi)*sqrt(s)*exp(a*s)*erfc(sqrt(a)*sqrt(s)) + 2/sqrt(a), 0, True)")
  expect_equal(mi_fmt(laplace_transform(t ^ (as_sym(1) / 2) * (t + a) ^ (-1), t, s)), "(-pi*sqrt(a)*exp(a*s)*erfc(sqrt(a)*sqrt(s)) + sqrt(pi)*sqrt(1/s), 0, True)")
  expect_equal(mi_fmt(laplace_transform(1 / (a * sqrt(t) + t ^ (3/2)), t, s)), "(pi*sqrt(a)*exp(a*s)*erfc(sqrt(a)*sqrt(s)), 0, True)")
  expect_equal(mi_fmt(laplace_transform((t + a) ^ b, t, s)), "(s^(-b - 1)*exp(a*s)*uppergamma(b + 1, a*s), 0, True)")
  expect_equal(mi_fmt(laplace_transform(t ^ 5 / (t + a), t, s)), "(120*expint(6, a*s)/s^5, 0, True)")
  expect_equal(mi_fmt(laplace_transform(exp(t), t, s)), "(1/(s - 1), 1, True)")
  expect_equal(mi_fmt(laplace_transform(exp(2 * t), t, s)), "(1/(s - 2), 2, True)")
  expect_equal(mi_fmt(laplace_transform(exp(a * t), t, s)), "(1/(-a + s), a, True)")
  expect_equal(mi_fmt(laplace_transform(exp(a * (t - b)), t, s)), "(exp(-a*b)/(-a + s), a, True)")
  expect_equal(mi_fmt(laplace_transform(t * exp(-a * t), t, s)), "((a + s)^(-2), -a, True)")
  expect_equal(mi_fmt(laplace_transform(t * exp(-a * (t - b)), t, s)), "(exp(a*b)/(a + s)^2, -a, True)")
  expect_equal(mi_fmt(laplace_transform(b * t * exp(-a * t), t, s)), "(b/(a + s)^2, -a, True)")
  expect_equal(mi_fmt(laplace_transform(exp(-a * exp(-t)), t, s)), "(lowergamma(s, a)/a^s, 0, True)")
  expect_equal(mi_fmt(laplace_transform(exp(-a * exp(t)), t, s)), "(a^s*uppergamma(-s, a), 0, True)")
  expect_equal(mi_fmt(laplace_transform(t ^ (as_sym(7) / 4) * exp(-8 * t) / gamma(as_sym(11) / 4), t, s)), "((s + 8)^(-11/4), -8, True)")
  expect_equal(mi_fmt(laplace_transform(t ^ (as_sym(3) / 2) * exp(-8 * t), t, s)), "(3*sqrt(pi)/(4*(s + 8)^(5/2)), -8, True)")
  expect_equal(mi_fmt(laplace_transform(t ^ a * exp(-a * t), t, s)), "((a + s)^(-a - 1)*gamma(a + 1), -a, True)")
  expect_equal(mi_fmt(laplace_transform(b * exp(-a * t ^ 2), t, s)), "(sqrt(pi)*b*exp(s^2/(4*a))*erfc(s/(2*sqrt(a)))/(2*sqrt(a)), 0, True)")
  expect_equal(mi_fmt(laplace_transform(exp(-2 * t ^ 2), t, s)), "(sqrt(2)*sqrt(pi)*exp(s^2/8)*erfc(sqrt(2)*s/4)/4, 0, True)")
  expect_equal(mi_fmt(laplace_transform(t * exp(-a * t ^ 2), t, s)), "(1/(2*a) - s*erfc(s/(2*sqrt(a)))/(4*sqrt(pi)*a^(3/2)), 0, True)")
  expect_equal(mi_fmt(laplace_transform(exp(-a / t), t, s)), "(2*sqrt(a)*sqrt(1/s)*besselk(1, 2*sqrt(a)*sqrt(s)), 0, True)")
  expect_equal(mi_fmt(laplace_transform(sqrt(t) * exp(-a / t), t, s, simplify = TRUE)), "(sqrt(pi)*(sqrt(a)*sqrt(s) + 1/2)*sqrt(s^(-3))*exp(-2*sqrt(a)*sqrt(s)), 0, True)")
  expect_equal(mi_fmt(laplace_transform(exp(-a / t) / sqrt(t), t, s)), "(sqrt(pi)*sqrt(1/s)*exp(-2*sqrt(a)*sqrt(s)), 0, True)")
  expect_equal(mi_fmt(laplace_transform(exp(-a / t) / (t * sqrt(t)), t, s)), "(sqrt(pi)*exp(-2*sqrt(a)*sqrt(s))/sqrt(a), 0, True)")
  expect_equal(mi_fmt(laplace_transform(t ^ 4 * exp(-2 / t), t, s)), "(8*sqrt(2)*(1/s)^(5/2)*besselk(5, 2*sqrt(2)*sqrt(s)), 0, True)")
  expect_equal(mi_fmt(laplace_transform(sinh(a * t), t, s)), "(a/(-a^2 + s^2), a, True)")
  expect_equal(mi_fmt(laplace_transform(b * sinh(a * t) ^ 2, t, s)), "(2*a^2*b/(-4*a^2*s + s^3), 2*a, True)")
  expect_equal(mi_fmt(laplace_transform(b * sinh(a * t) ^ 2, t, s, simplify = TRUE)), "(2*a^2*b/(s*(-4*a^2 + s^2)), 2*a, True)")
  expect_equal(mi_fmt(laplace_transform(cosh(2 * t), t, s)), "(s/(s^2 - 4), 2, True)")
  expect_equal(mi_fmt(laplace_transform(cosh(a * t), t, s)), "(s/(-a^2 + s^2), a, True)")
  expect_equal(mi_fmt(laplace_transform(cosh(a * t) ^ 2, t, s, simplify = TRUE)), "((2*a^2 - s^2)/(s*(4*a^2 - s^2)), 2*a, True)")
  expect_equal(mi_fmt(laplace_transform(sinh(x + 3), x, s, simplify = TRUE)), "((s*sinh(3) + cosh(3))/(s^2 - 1), 1, True)")
  expect_equal(mi_fmt(laplace_transform(sinh(a * t) * cosh(a * t), t, s, simplify = TRUE)), "(a/(-4*a^2 + s^2), 2*a, True)")
  expect_equal(mi_fmt(laplace_transform(sinh(a * t) / t, t, s)), "(log((a + s)/(-a + s))/2, a, True)")
  expect_equal(mi_fmt(laplace_transform(t ^ (-as_sym(3) / 2) * sinh(a * t), t, s)), "(-sqrt(pi)*(sqrt(-a + s) - sqrt(a + s)), a, True)")
  expect_equal(mi_fmt(laplace_transform(t ^ (as_sym(3) / 7) * cosh(a * t), t, s)), "(((a + s)^(-10/7) + (-a + s)^(-10/7))*gamma(10/7)/2, a, True)")
  expect_equal(mi_fmt(laplace_transform(log(t), t, s, simplify = TRUE)), "((-log(s) - EulerGamma)/s, 0, True)")
  expect_equal(mi_fmt(laplace_transform(-log(t / a), t, s, simplify = TRUE)), "((log(a) + log(s) + EulerGamma)/s, 0, True)")
  expect_equal(mi_fmt(laplace_transform(log(1 + a * t), t, s)), "(-exp(s/a)*Ei(-s/a)/s, 0, True)")
  expect_equal(mi_fmt(laplace_transform(log(t + a), t, s, simplify = TRUE)), "((s*log(a) - exp(s/a)*Ei(-s/a))/s^2, 0, True)")
  expect_equal(mi_fmt(laplace_transform(log(t) / sqrt(t), t, s, simplify = TRUE)), "(sqrt(pi)*(-log(s) - log(4) - EulerGamma)/sqrt(s), 0, True)")
  expect_equal(mi_fmt(laplace_transform(t ^ (as_sym(5) / 2) * log(t), t, s, simplify = TRUE)), "(sqrt(pi)*(-15*log(s) - log(1073741824) - 15*EulerGamma + 46)/(8*s^(7/2)), 0, True)")
  expect_equal(mi_fmt(laplace_transform(log(t) ^ 2, t, s, simplify = TRUE)), "(((log(s) + EulerGamma)^2 + pi^2/6)/s, 0, True)")
  expect_equal(mi_fmt(laplace_transform(exp(-a * t) * log(t), t, s, simplify = TRUE)), "((-log(a + s) - EulerGamma)/(a + s), -a, True)")
  expect_equal(mi_fmt(laplace_transform(sin(a * t), t, s)), "(a/(a^2 + s^2), 0, True)")
  expect_equal(mi_fmt(laplace_transform(Abs(sin(a * t)), t, s)), "(a*coth(pi*s/(2*a))/(a^2 + s^2), 0, True)")
  expect_equal(mi_fmt(laplace_transform(sin(a * t) / t, t, s)), "(atan(a/s), 0, True)")
  expect_equal(mi_fmt(laplace_transform(sin(a * t) ^ 2 / t, t, s)), "(log(4*a^2/s^2 + 1)/4, 0, True)")
  expect_equal(mi_fmt(laplace_transform(sin(a * t) ^ 2 / t ^ 2, t, s)), "(a*atan(2*a/s) - s*log(4*a^2/s^2 + 1)/4, 0, True)")
  expect_equal(mi_fmt(laplace_transform(cos(a * t), t, s)), "(s/(a^2 + s^2), 0, True)")
  expect_equal(mi_fmt(laplace_transform(cos(a * t) ^ 2, t, s)), "((2*a^2 + s^2)/(s*(4*a^2 + s^2)), 0, True)")
  expect_equal(mi_fmt(laplace_transform(sin(a * t) * sin(b * t), t, s)), "(2*a*b*s/((s^2 + (a - b)^2)*(s^2 + (a + b)^2)), 0, True)")
  expect_equal(mi_fmt(laplace_transform(cos(a * t) * sin(b * t), t, s)), "(b*(-a^2 + b^2 + s^2)/((s^2 + (a - b)^2)*(s^2 + (a + b)^2)), 0, True)")
  expect_equal(mi_fmt(laplace_transform(cos(a * t) * cos(b * t), t, s)), "(s*(a^2 + b^2 + s^2)/((s^2 + (a - b)^2)*(s^2 + (a + b)^2)), 0, True)")
  expect_equal(mi_fmt(laplace_transform(-a * t * cos(a * t) + sin(a * t), t, s, simplify = TRUE)), "(2*a^3/(a^4 + 2*a^2*s^2 + s^4), 0, True)")
  expect_equal(mi_fmt(laplace_transform(c * exp(-b * t) * sin(a * t), t, s)), "(a*c/(a^2 + (b + s)^2), -b, True)")
  expect_equal(mi_fmt(laplace_transform(c * exp(-b * t) * cos(a * t), t, s)), "(c*(b + s)/(a^2 + (b + s)^2), -b, True)")
  expect_equal(mi_fmt(laplace_transform(erf(a * t), t, s)), "(exp(s^2/(4*a^2))*erfc(s/(2*a))/s, 0, True)")
  expect_equal(mi_fmt(laplace_transform(besselj(0, a * t), t, s)), "(1/sqrt(a^2 + s^2), 0, True)")
  expect_equal(mi_fmt(laplace_transform(besselj(1, a * t), t, s, simplify = TRUE)), "(a/(a^2 + s^2 + s*sqrt(a^2 + s^2)), 0, True)")
  expect_equal(mi_fmt(laplace_transform(besselj(2, a * t), t, s, simplify = TRUE)), "(a^2/(sqrt(a^2 + s^2)*(s + sqrt(a^2 + s^2))^2), 0, True)")
  expect_equal(mi_fmt(laplace_transform(t * besselj(0, a * t), t, s)), "(s/(a^2 + s^2)^(3/2), 0, True)")
  expect_equal(mi_fmt(laplace_transform(t * besselj(1, a * t), t, s)), "(a/(a^2 + s^2)^(3/2), 0, True)")
  expect_equal(mi_fmt(laplace_transform(t ^ 2 * besselj(2, a * t), t, s)), "(3*a^2/(a^2 + s^2)^(5/2), 0, True)")
  expect_equal(mi_fmt(laplace_transform(besselj(0, a * sqrt(t ^ 2 + b * t)), t, s, simplify = TRUE)), "(exp(b*(s - sqrt(a^2 + s^2)))/sqrt(a^2 + s^2), 0, True)")
  expect_equal(mi_fmt(laplace_transform(besseli(0, a * t), t, s)), "(1/sqrt(-a^2 + s^2), a, True)")
  expect_equal(mi_fmt(laplace_transform(besseli(1, a * t), t, s, simplify = TRUE)), "(a/(-a^2 + s^2 + s*sqrt(-a^2 + s^2)), a, True)")
  expect_equal(mi_fmt(laplace_transform(besseli(2, a * t), t, s, simplify = TRUE)), "(a^2/(sqrt(-a^2 + s^2)*(s + sqrt(-a^2 + s^2))^2), a, True)")
  expect_equal(mi_fmt(laplace_transform(t * besseli(0, a * t), t, s)), "(s/(-a^2 + s^2)^(3/2), a, True)")
  expect_equal(mi_fmt(laplace_transform(t * besseli(1, a * t), t, s)), "(a/(-a^2 + s^2)^(3/2), a, True)")
  expect_equal(mi_fmt(laplace_transform(t ^ 2 * besseli(2, a * t), t, s)), "(3*a^2/(-a^2 + s^2)^(5/2), a, True)")
  expect_equal(mi_fmt(laplace_transform(bessely(0, a * t), t, s)), "(-2*asinh(s/a)/(pi*sqrt(a^2 + s^2)), 0, True)")
  expect_equal(mi_fmt(laplace_transform(besselk(0, a * t), t, s)), "(log((s + sqrt(-a^2 + s^2))/a)/sqrt(-a^2 + s^2), -a, True)")
  expect_equal(mi_fmt(laplace_transform(sin(a * t) ^ 4, t, s, simplify = TRUE)), "(24*a^4/(s*(64*a^4 + 20*a^2*s^2 + s^4)), 0, True)")
  expect_equal(mi_fmt(laplace_transform(Heaviside(t - 1) * cos(t - 1), t, s)), "(s*exp(-s)/(s^2 + 1), 0, True)")
  expect_equal(mi_fmt(laplace_transform(a * f(t), t, w)), "(a*LaplaceTransform(f(t), t, w), -oo, True)")
  expect_equal(mi_fmt(laplace_transform(a * Heaviside(t + 1) * f(t + 1), t, s)), "(a*LaplaceTransform(f(t + 1), t, s), -oo, True)")
  expect_equal(mi_fmt(laplace_transform(a * Heaviside(t - 1) * f(t - 1), t, s)), "(a*LaplaceTransform(f(t), t, s)*exp(-s), -oo, True)")
  expect_equal(mi_fmt(laplace_transform(b * f(t / a), t, s)), "(a*b*LaplaceTransform(f(t), t, a*s), -oo, True)")
  expect_equal(mi_fmt(laplace_transform(exp(-f(x) * t), t, s)), "(1/(s + f(x)), -re(f(x)), True)")
  expect_equal(mi_fmt(laplace_transform(exp(-a * t) * f(t), t, s)), "(LaplaceTransform(f(t), t, a + s), -oo, True)")
  expect_equal(mi_fmt(laplace_transform(sinh(a * t) * f(t), t, s)), "(LaplaceTransform(f(t), t, -a + s)/2 - LaplaceTransform(f(t), t, a + s)/2, -oo, True)")
  expect_equal(mi_fmt(laplace_transform(sinh(a * t) * t, t, s, simplify = TRUE)), "(2*a*s/(a^4 - 2*a^2*s^2 + s^4), a, True)")
  expect_equal(mi_fmt(laplace_transform(cosh(a * t) * f(t), t, s)), "(LaplaceTransform(f(t), t, -a + s)/2 + LaplaceTransform(f(t), t, a + s)/2, -oo, True)")
  expect_equal(mi_fmt(laplace_transform(cosh(a * t) * t, t, s, simplify = TRUE)), "(1/(2*(a + s)^2) + 1/(2*(a - s)^2), a, True)")
  expect_equal(mi_fmt(laplace_transform(sin(a * t) * f(t), t, s, simplify = TRUE)), "(I*(-LaplaceTransform(f(t), t, -I*a + s) + LaplaceTransform(f(t), t, I*a + s))/2, -oo, True)")
  expect_equal(mi_fmt(laplace_transform(sin(f(t)), t, s)), "(LaplaceTransform(sin(f(t)), t, s), -oo, True)")
  expect_equal(mi_fmt(laplace_transform(sin(a * t) * t, t, s, simplify = TRUE)), "(2*a*s/(a^4 + 2*a^2*s^2 + s^4), 0, True)")
  expect_equal(mi_fmt(laplace_transform(cos(a * t) * f(t), t, s)), "(LaplaceTransform(f(t), t, -I*a + s)/2 + LaplaceTransform(f(t), t, I*a + s)/2, -oo, True)")
  expect_equal(mi_fmt(laplace_transform(cos(a * t) * t, t, s, simplify = TRUE)), "((-a^2 + s^2)/(a^4 + 2*a^2*s^2 + s^4), 0, True)")
  expect_equal(mi_fmt(laplace_transform(t ^ 2 * exp(-t ^ 2), t, s)), "(sqrt(pi)*s^2*exp(s^2/4)*erfc(s/2)/8 - s/4 + sqrt(pi)*exp(s^2/4)*erfc(s/2)/4, 0, True)")
  expect_equal(mi_fmt(laplace_transform((a * t ^ 2 + b * t + c) * f(t), t, s)), "(a*Derivative(LaplaceTransform(f(t), t, s), (s, 2)) - b*Derivative(LaplaceTransform(f(t), t, s), s) + c*LaplaceTransform(f(t), t, s), -oo, True)")
  expect_equal(mi_fmt(laplace_transform(t ^ np * g(t), t, s)), "((-1)^np*Derivative(LaplaceTransform(g(t), t, s), (s, np)), -oo, True)")
  expect_equal(mi_fmt(laplace_transform(diff(f(t), list(t, 1)), t, s, noconds = TRUE)), "s*LaplaceTransform(f(t), t, s) - f(0)")
  expect_equal(mi_fmt(laplace_transform(diff(f(t), list(t, 3)), t, s, noconds = TRUE)), "s^3*LaplaceTransform(f(t), t, s) - s^2*f(0) - s*Subs(Derivative(f(t), t), t, 0) - Subs(Derivative(f(t), (t, 2)), t, 0)")
  expect_equal(mi_fmt(laplace_transform(diff(f(x, t, w), t, 2), t, s)), "(s^2*LaplaceTransform(f(x, t, w), t, s) - s*f(x, 0, w) - Subs(Derivative(f(x, t, w), t), t, 0), -oo, True)")
  expect_equal(mi_fmt(laplace_transform(10 * diff(f(t), list(t, 1)), t, s, noconds = TRUE)), "10*s*LaplaceTransform(f(t), t, s) - 10*f(0)")
  expect_equal(mi_fmt(laplace_transform(a * f(b * t) + g(c * t), t, s, noconds = TRUE)), "a*LaplaceTransform(f(t), t, s/b)/b + LaplaceTransform(g(t), t, s/c)/c")
  expect_equal(mi_fmt(laplace_transform(f(t) * g(t), t, s, noconds = TRUE)), "LaplaceTransform(f(t)*g(t), t, s)")
  expect_equal(mi_fmt(laplace_transform(b * f(a * t), t, s, noconds = TRUE)), "b*LaplaceTransform(f(t), t, s/a)/a")
  expect_equal(mi_fmt(laplace_transform(3 * exp(t) * Heaviside(t), t, s)), "(3/(s - 1), 1, True)")
  expect_equal(mi_fmt(laplace_transform(2 * sin(t) * Heaviside(t), t, s, simplify = TRUE)), "(2/(s^2 + 1), 0, True)")
  expect_equal(mi_fmt(laplace_transform((t + 4) * a, t, s)), "(a*(4*s + 1)/s^2, 0, True)")
  expect_equal(mi_fmt(laplace_transform((t - a) ^ b * exp(-c * (t - a)) * Heaviside(t - a), t, s)), "((c + s)^(-b - 1)*exp(-a*s)*gamma(b + 1), -c, True)")
  expect_equal(mi_fmt(laplace_transform((exp(2 * t) - 1) * exp(-b - t) * Heaviside(t) / 2, t, s, noconds = TRUE, simplify = TRUE)), "exp(-b)/(s^2 - 1)")
  expect_equal(mi_fmt(laplace_transform(Heaviside(t), t, s)), "(1/s, 0, True)")
  expect_equal(mi_fmt(laplace_transform(Heaviside(t - a), t, s)), "(exp(-a*s)/s, 0, True)")
  expect_equal(mi_fmt(laplace_transform(Heaviside(t - 1), t, s)), "(exp(-s)/s, 0, True)")
  expect_equal(mi_fmt(laplace_transform(Heaviside(2 * t - 4), t, s)), "(exp(-2*s)/s, 0, True)")
  expect_equal(mi_fmt(laplace_transform(Heaviside(2 * t + 4), t, s)), "(1/s, 0, True)")
  expect_equal(mi_fmt(laplace_transform(Heaviside(-2 * t + 4), t, s, simplify = TRUE)), "(1/s - exp(-2*s)/s, 0, True)")
  expect_equal(mi_fmt(laplace_transform(g(t) * Heaviside(t - w), t, s)), "(LaplaceTransform(g(t)*Heaviside(t - w), t, s), -oo, True)")
  expect_equal(mi_fmt(laplace_transform(Heaviside(t - a) * g(t), t, s)), "(LaplaceTransform(g(a + t), t, s)*exp(-a*s), -oo, True)")
  expect_equal(mi_fmt(laplace_transform(Heaviside(t + a) * g(t), t, s)), "(LaplaceTransform(g(t), t, s), -oo, True)")
  expect_equal(mi_fmt(laplace_transform(Heaviside(-t + a) * g(t), t, s)), "(LaplaceTransform(g(t), t, s) - LaplaceTransform(g(a + t), t, s)*exp(-a*s), -oo, True)")
  expect_equal(mi_fmt(laplace_transform(Heaviside(-t - a) * g(t), t, s)), "(0, 0, True)")
  expect_equal(mi_fmt(laplace_transform(Piecewise(list(1, Eq(t, 1)), list(2, TRUE)), t, s)), "(LaplaceTransform(Piecewise((1, Eq(t, 1)), (2, True)), t, s), -oo, True)")
  expect_equal(mi_fmt(laplace_transform(SingularityFunction(t, a, -1), t, s)), "(exp(-a*s), -oo, True)")
  expect_equal(mi_fmt(laplace_transform(SingularityFunction(t, a, 1), t, s)), "(exp(-a*s)/s^2, 0, True)")
  expect_equal(mi_fmt(laplace_transform(SingularityFunction(t, a, x), t, s)), "(LaplaceTransform(SingularityFunction(t, a, x), t, s), -oo, True)")
  expect_equal(mi_fmt(laplace_transform(t ^ 3 * log(t), t, s, noconds = TRUE, simplify = TRUE)), "(-6*log(s) - 6*EulerGamma + 11)/s^4")
})
